from google.cloud import documentai
from google.api_core.client_options import ClientOptions

def extract_invoice_fields(payload, config=None):
    config = config or {}
    project_id = os.environ["GOOGLE_PROJECT_ID"]
    location = os.environ.get("GOOGLE_LOCATION", "us")
    processor_id = os.environ["DOCAI_INVOICE_PROCESSOR_ID"]
    mime_type = payload["mime_type"]
    file_content = payload["content"]

    # Provider-specific client setup
    opts = ClientOptions(api_endpoint=f"{location}-documentai.googleapis.com")
    client = documentai.DocumentProcessorServiceClient(client_options=opts)

    # The full resource name of the processor
    name = client.processor_path(project_id, location, processor_id)

    # Prepare the document
    raw_document = documentai.RawDocument(content=file_content, mime_type=mime_type)

    # Configure the process request
    request = documentai.ProcessRequest(name=name, raw_document=raw_document)

    # Make the API call
    response = client.process_document(request=request)
    document = response.document

    # Parse the response
    extracted_data = {
        "vendor": None,
        "date": None,
        "total": None,
        "line_items": []
    }

    for entity in document.entities:
        entity_type = entity.type_
        if entity_type == "vendor_name":
            extracted_data["vendor"] = entity.mention_text
        elif entity_type == "invoice_date":
            if entity.normalized_value:
                date = entity.normalized_value.date_value
                extracted_data["date"] = f"{date.year}-{date.month:02d}-{date.day:02d}"
        elif entity_type == "total_amount":
            if entity.normalized_value:
                 money = entity.normalized_value.money_value
                 extracted_data["total"] = float(f"{money.units}.{abs(money.nanos):09d}")
        elif entity_type == "line_item":
            line_item = {}
            for prop in entity.properties:
                if prop.type_ == "line_item/description":
                    line_item["description"] = prop.mention_text
                elif prop.type_ == "line_item/amount":
                    if prop.normalized_value:
                         money = prop.normalized_value.money_value
                         line_item["amount"] = float(f"{money.units}.{abs(money.nanos):09d}")
            if line_item:
                extracted_data["line_items"].append(line_item)
    result = extracted_data
    return result
